  let stormArtReady=false;StarStormArt.ready.then(()=>{stormArtReady=true;if(state==='home')homeUI();});
  const records={tap:0,dodge:0,storm:0};let mode=2,sound=true;
  try { modes.forEach(m=>records[m.id]=Math.max(0,Number(localStorage.getItem(m.key))||0));sound=localStorage.getItem('stars-sound')!=='off'; } catch {}
  const slinging=()=>false;
