    document.body.classList.toggle('storm-layout',active);document.body.classList.toggle('storm-turn-left',active&&size.rotation===-90);document.body.classList.toggle('storm-turn-right',active&&size.rotation===90);document.body.classList.toggle('storm-upside-down',active&&size.rotation===-180);
