    $('nova-home-rank').hidden=true;$('storm-shop').hidden=true;$('mode-art').dataset.mode=current.id;document.body.dataset.game=current.id;StarCosmicArt.drawCover($('cosmic-home-cover'),current.id);$('start').setAttribute('aria-label',current.name+' – endlos spielen');
    $('start').disabled=current.id==='storm'&&!stormArtReady;$('start').classList.toggle('loading-art',current.id==='storm'&&!stormArtReady);$('mini-tap-best').textContent=records.tap.toLocaleString('de-DE');$('mini-dodge-best').textContent=duration(records.dodge);
