  function novaFeedback(events){for(const e of events){if(e.kind==='shot')effect('shot');if(e.kind==='warning')effect('warning');if(e.kind==='dimension-open'){effect('portal');}if(e.kind==='dimension-close')effect('portal-close');if(e.kind==='drone')effect('drone');if(e.kind==='drone-impact'&&performance.now()-lastBoom>130){lastBoom=performance.now();effect('explode');}if(e.kind==='healing'){effect('heal');}if(e.kind==='hammer'&&performance.now()-lastBoom>130){lastBoom=performance.now();effect('explode');}if(e.kind==='currency'){novaNotice=e.name+' · '+run.arenaName+' · 1 zweite Chance';novaNoticeUntil=run.elapsed+4500;effect('currency');}if(e.kind==='warning'){$('encouragement').textContent='Warnzone! Aus der roten Markierung herausbewegen.';}if(e.kind==='ability'){effect('ability');}if(e.kind==='hurt'){hearts();pulse($('nova-field'),'field-hit');effect('hit');}if(e.kind==='explode'&&performance.now()-lastBoom>130){lastBoom=performance.now();effect(e.boss?'boss':'explode');}if(e.kind==='boss'){novaBossName=e.name||'BOSS';novaBossUntil=modes[mode].id==='storm'?0:run.elapsed+2200;effect('boss');$('encouragement').textContent=(e.name||'Boss')+' erscheint';}}}
